dashboard.definition:
{
	"title": "Data Pipeline Overview",
	"description": "",
	"inputs": {
		"input_xV9baORe": {
			"options": {
				"defaultValue": "-30d@d,now",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Proxy", "value": "logserv_proxy"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_7NM08jn4": {
			"dataSources": {
				"primary": "ds_qvNrhKle"
			},
			"options": {
				"backgroundColor": "transparent",
				"nodeColor": "#0877a6",
				"nodeHeight": 23,
				"nodeSpacingX": 220,
				"nodeSpacingY": 21,
				"nodeWidth": 202,
				"showValueCounts": false
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Source to sourcetype mapping",
			"type": "splunk.linkgraph"
		},
		"viz_E6VoPgPK": {
			"dataSources": {
				"primary": "ds_mRjpSfGy"
			},
			"description": "",
			"options": {
				"backgroundColor": "transparent",
				"majorValue": "> sparklineValues | lastPoint()",
				"sparklineDisplay": "off",
				"sparklineValues": "> primary | seriesByName('host_count')",
				"trendValue": "> sparklineValues | delta(-2)"
			},
			"title": "Active Hosts",
			"type": "splunk.singlevalue"
		},
		"viz_RaSQZQg0": {
			"dataSources": {
				"primary": "ds_znDIWqYG"
			},
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide",
				"yAxisScale": "log"
			},
			"title": "Host Event Count",
			"type": "splunk.line"
		},
		"viz_Rr0ozI8N": {
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_TWx0q4MO": {
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_YGJifJFJ": {
			"dataSources": {
				"primary": "ds_gn5P2213"
			},
			"description": "",
			"eventHandlers": [
				{
					"type": "drilldown.linkToDashboard",
					"options": {
						"app": "splunk_app_sap_logserv",
						"dashboard": "logserv_host_details",
						"newTab": true,
						"tokens": [
							{
								"token": "host_name",
								"value": "row.Host.value"
							}
						]
					}
				}
			],
			"options": {
				"backgroundColor": "transparent",
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
				}
			},
			"title": "Host Latest Activity",
			"type": "splunk.table"
		},
		"viz_nraRnnPr": {
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_pZLsO3n7": {
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {
				"primary": "ds_nav_go"
			},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6",
				"majorColor": "#ffffff",
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorFontSize": 14
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		}
	},
	"dataSources": {
		"ds_gn5P2213": {
			"name": "host_latest_activity",
			"options": {
				"query": "`sap_logserv_idx_macro` \r\n| fields source, sourcetype, host, _time\r\n| dedup host, source, sourcetype\r\n| dedup host\r\n| fields host, _time\r\n| stats count by host, _time\r\n| eval _time = now() - _time \r\n| sort + _time\r\n| eval elapsed_time = case(_time < 60, _time.\" seconds ago\",\r\n_time < 3600, round(_time/60).\" minutes ago\",\r\n_time < 86400, round(_time/3600).\" hours ago\",\r\ntrue(), round(_time/86400).\" days ago\")\r\n| dedup host\r\n| table host, elapsed_time\r\n| rename host AS \"Host\", elapsed_time AS \"Latest Activity\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mRjpSfGy": {
			"name": "single_value_search",
			"options": {
				"query": "`sap_logserv_idx_macro` \r\n| stats dc(host) AS host_count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_qvNrhKle": {
			"name": "link_map_search",
			"options": {
				"enableSmartSources": true,
				"query": "`sap_logserv_idx_macro` \r\n| fields source, sourcetype, host\r\n| dedup host, source, sourcetype\r\n| stats count by sourcetype source, host\r\n| fields - count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_znDIWqYG": {
			"name": "line_chart_host_events",
			"options": {
				"query": "`sap_logserv_idx_macro` \r\n| fields source, sourcetype, host\r\n| timechart span=1d limit=0 count by host",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {
				"query": "| makeresults | eval label=\"Go >\"",
				"queryParameters": {
					"earliest": "-1m",
					"latest": "now"
				}
			}
		}
	},
	"layout": {
		"globalInputs": [
			"input_xV9baORe",
			"input_nav_dropdown"
		],
		"layoutDefinitions": {
			"layout_1": {
				"options": {
					"display": "fit-to-width",
					"height": 995,
					"width": 1600
				},
				"structure": [
					{
						"item": "viz_TWx0q4MO",
						"position": {
							"h": 600,
							"w": 1140,
							"x": 450,
							"y": 355
						},
						"type": "block"
					},
					{
						"item": "viz_pZLsO3n7",
						"position": {
							"h": 300,
							"w": 1590,
							"x": 0,
							"y": 45
						},
						"type": "block"
					},
					{
						"item": "viz_RaSQZQg0",
						"position": {
							"h": 300,
							"w": 1580,
							"x": 0,
							"y": 45
						},
						"type": "block"
					},
					{
						"item": "viz_7NM08jn4",
						"position": {
							"h": 600,
							"w": 1130,
							"x": 450,
							"y": 355
						},
						"type": "block"
					},
					{
						"item": "viz_nraRnnPr",
						"position": {
							"h": 140,
							"w": 440,
							"x": 0,
							"y": 355
						},
						"type": "block"
					},
					{
						"item": "viz_Rr0ozI8N",
						"position": {
							"h": 450,
							"w": 440,
							"x": 0,
							"y": 505
						},
						"type": "block"
					},
					{
						"item": "viz_E6VoPgPK",
						"position": {
							"h": 140,
							"w": 440,
							"x": 0,
							"y": 355
						},
						"type": "block"
					},
					{
						"item": "viz_YGJifJFJ",
						"position": {
							"h": 450,
							"w": 440,
							"x": 0,
							"y": 505
						},
						"type": "block"
					},
					{
						"item": "viz_nav_go",
						"type": "block",
						"position": {
							"x": 1470,
							"y": 0,
							"w": 120,
							"h": 35
						}
					}
				],
				"type": "absolute"
			}
		},
		"tabs": {
			"items": [
				{
					"label": "New tab",
					"layoutId": "layout_1"
				}
			]
		}
	}
}
